SELECT (CASE WHEN (eixo_1.no_dependencia_admin = 'Privada') THEN eixo_1.mantenedora ELSE eixo_1.instituicao END) AS calculation_838513978982854656,   eixo_1.municipio_do_local_da_oferta AS municipio_do_local_da_oferta,   eixo_1.no_dependencia_admin AS no_dependencia_admin,   eixo_1.nome_curso_catalogo_guia AS nome_curso_catalogo_guia,   eixo_1.nome_da_ue AS nome_da_ue,   SUM(CAST(eixo_1.number of records AS BIGINT)) AS sum:number of records:ok,   eixo_1.uf_do_local_da_oferta AS uf_do_local_da_oferta,   CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) AS yr:data_de_inicio:ok FROM eixo_1 WHERE ((eixo_1.uf_do_local_da_oferta = 'PE') AND (NOT ((eixo_1.nome da sit matricula (situacao detalhada) NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR (eixo_1.nome da sit matricula (situacao detalhada) IS NULL))) AND (NOT (eixo_1.situacao_da_turma IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY calculation_838513978982854656,   municipio_do_local_da_oferta,   no_dependencia_admin,   nome_curso_catalogo_guia,   nome_da_ue,   uf_do_local_da_oferta,   yr:data_de_inicio:ok;
